/**
 * Docsify 搜索插件 - 基于预生成索引
 * 性能优化：一次性加载索引文件，避免逐个加载所有 md 文件
 */
(function () {
    var INDEX_PATH = 'search-index.json';
    var indexData = null;
    var searchInput = null;
    var resultContainer = null;

    // 加载索引文件
    function loadIndex(callback) {
        if (indexData) {
            callback(indexData);
            return;
        }

        var xhr = new XMLHttpRequest();
        xhr.open('GET', INDEX_PATH, true);
        xhr.onload = function () {
            if (xhr.status === 200) {
                try {
                    indexData = JSON.parse(xhr.responseText);
                    callback(indexData);
                } catch (e) {
                    console.error('Failed to parse search index:', e);
                    callback([]);
                }
            } else {
                console.error('Failed to load search index:', xhr.status);
                callback([]);
            }
        };
        xhr.onerror = function () {
            console.error('Failed to load search index');
            callback([]);
        };
        xhr.send();
    }

    // 搜索函数
    function search(query, index) {
        if (!query || !index) return [];

        query = query.toLowerCase();
        var results = [];

        for (var i = 0; i < index.length; i++) {
            var item = index[i];
            var title = (item.t || '').toLowerCase();
            var content = (item.c || '').toLowerCase();

            // 标题匹配权重更高
            if (title.indexOf(query) !== -1) {
                results.push({
                    id: item.id,
                    title: item.t,
                    snippet: getSnippet(item.c, query),
                    score: 100
                });
            } else if (content.indexOf(query) !== -1) {
                results.push({
                    id: item.id,
                    title: item.t,
                    snippet: getSnippet(item.c, query),
                    score: 10
                });
            }
        }

        // 按分数排序
        results.sort(function (a, b) {
            return b.score - a.score;
        });

        return results.slice(0, 50); // 最多返回 50 条结果
    }

    // 获取搜索结果摘要
    function getSnippet(content, query) {
        if (!content) return '';

        var index = content.toLowerCase().indexOf(query.toLowerCase());
        if (index === -1) {
            return content.substring(0, 150) + '...';
        }

        var start = Math.max(0, index - 50);
        var end = Math.min(content.length, index + query.length + 100);
        var snippet = content.substring(start, end);

        if (start > 0) snippet = '...' + snippet;
        if (end < content.length) snippet = snippet + '...';

        return snippet;
    }

    // 创建搜索 UI
    function createSearchUI() {
        // 查找搜索输入框
        searchInput = document.querySelector('.search input, #search-input');
        if (!searchInput) {
            // 创建搜索框
            var searchBox = document.createElement('div');
            searchBox.className = 'search';
            searchBox.innerHTML = '<input type="search" placeholder="搜索..." />';
            searchInput = searchBox.querySelector('input');

            // 插入到侧边栏顶部
            var sidebar = document.querySelector('.sidebar');
            if (sidebar) {
                sidebar.insertBefore(searchBox, sidebar.firstChild);
            }
        }

        // 创建结果容器
        resultContainer = document.createElement('div');
        resultContainer.className = 'search-results';
        resultContainer.style.cssText = 'display:none;position:absolute;top:100%;left:0;right:0;background:#fff;border:1px solid #ddd;border-radius:4px;max-height:400px;overflow-y:auto;z-index:1000;box-shadow:0 2px 8px rgba(0,0,0,0.15);';

        // 插入到搜索框后面
        searchInput.parentNode.style.position = 'relative';
        searchInput.parentNode.appendChild(resultContainer);

        // 绑定搜索事件
        var debounceTimer = null;
        searchInput.addEventListener('input', function () {
            var query = this.value.trim();
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(function () {
                performSearch(query);
            }, 200);
        });

        // 点击外部关闭结果
        document.addEventListener('click', function (e) {
            if (!searchInput.contains(e.target) && !resultContainer.contains(e.target)) {
                resultContainer.style.display = 'none';
            }
        });
    }

    // 执行搜索
    function performSearch(query) {
        if (!query) {
            resultContainer.style.display = 'none';
            return;
        }

        loadIndex(function (index) {
            var results = search(query, index);
            displayResults(results, query);
        });
    }

    // 显示搜索结果
    function displayResults(results, query) {
        if (results.length === 0) {
            resultContainer.innerHTML = '<div style="padding:12px;color:#666;">没有找到相关结果</div>';
            resultContainer.style.display = 'block';
            return;
        }

        var html = '<div style="padding:8px 12px;color:#666;font-size:12px;">找到 ' + results.length + ' 个结果</div>';

        results.forEach(function (result) {
            var title = highlightText(result.title, query);
            var snippet = highlightText(result.snippet, query);

            html += '<a href="' + result.id + '" class="search-result-item" style="display:block;padding:12px;border-bottom:1px solid #eee;text-decoration:none;color:inherit;">';
            html += '<div style="font-weight:500;margin-bottom:4px;">' + title + '</div>';
            html += '<div style="font-size:12px;color:#666;line-height:1.5;">' + snippet + '</div>';
            html += '</a>';
        });

        resultContainer.innerHTML = html;
        resultContainer.style.display = 'block';
    }

    // 高亮搜索关键词
    function highlightText(text, query) {
        if (!text || !query) return text || '';

        var regex = new RegExp('(' + escapeRegExp(query) + ')', 'gi');
        return text.replace(regex, '<mark style="background:#fff3cd;padding:0 2px;">$1</mark>');
    }

    // 转义正则表达式特殊字符
    function escapeRegExp(string) {
        return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    // Docsify 插件入口
    function(hook, vm) {
        hook.ready(function () {
            createSearchUI();
        });

        hook.afterEach(function (html) {
            return html;
        });
    }
})();
